//! `mt config` — inspect the effective merged configuration.
//!
//! Read-only: never writes. `show` (the default action) prints the effective
//! config assembled from every layer (embedded floor, XDG global defaults,
//! ancestor `.mindtape/defaults.toml` files, the project's own
//! `.mindtape/config.toml`); `--origin` lists the contributing layers instead;
//! `--defaults` prints just the embedded floor, independent of any project.
//! `schema` prints the JSON Schema for `.mindtape/config.toml`, generated by
//! the same [`mindtape::config_schema_json`] that `mt install` writes to disk.

use std::path::Path;

use crate::diag::Result;
use mindtape::{
    LayerSource, PackOrigin, RuleOrigin, config_schema_json, embedded_defaults, load_config_layered,
};

use crate::util;

/// Arguments for `config`.
#[derive(Debug, clap::Args)]
pub struct ConfigArgs {
    #[command(subcommand)]
    action: Option<ConfigAction>,
}

/// `mt config` sub-actions.
#[derive(Debug, clap::Subcommand)]
enum ConfigAction {
    /// Print the config mt uses, with every layer merged. This is the default.
    Show(ShowArgs),
    /// Print the JSON Schema for `.mindtape/config.toml`. Works outside a project.
    Schema,
}

/// Arguments for `mt config show`.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ShowArgs {
    /// Instead of the config, list the layers it comes from, lowest priority
    /// first, and the layer each rule comes from.
    #[arg(long, alias = "sources", conflicts_with = "defaults")]
    pub origin: bool,

    /// Print only the built-in defaults. Works outside a project.
    #[arg(long, conflicts_with = "origin")]
    pub defaults: bool,

    /// Print JSON instead of TOML.
    #[arg(long, conflicts_with_all = ["origin", "defaults"])]
    pub json: bool,
}

/// Run the `config` command.
///
/// # Errors
/// Returns an error if the current directory is not inside a Mindtape
/// project (not required for `--defaults`, which is project-independent), or
/// the layered config fails to load.
pub fn run(args: &ConfigArgs) -> Result<()> {
    let show_args = match &args.action {
        None => ShowArgs::default(),
        Some(ConfigAction::Show(show_args)) => show_args.clone(),
        Some(ConfigAction::Schema) => {
            print!("{}", render_schema());
            return Ok(());
        }
    };
    if show_args.defaults {
        println!("{}", embedded_defaults().trim_end());
        return Ok(());
    }
    let root = util::resolve_root()?;
    let text = if show_args.origin {
        render_origin(&root)?
    } else {
        render_effective(&root, show_args.json)?
    };
    print!("{text}");
    Ok(())
}

/// Render the effective merged config for `root` as TOML (or, with `json`,
/// pretty-printed JSON) text. Emits the merged `toml::Table` directly (the
/// same document that feeds `Config`'s typed deserialization) rather than
/// serializing `Config` itself, since the config structs derive only
/// `Deserialize`.
///
/// # Errors
/// Returns an error if any config layer fails to load or the table fails to
/// serialize.
pub(crate) fn render_effective(root: &Path, json: bool) -> Result<String> {
    let table = mindtape::merged_config_table(root)?;
    if json {
        Ok(format!("{}\n", serde_json::to_string_pretty(&table)?))
    } else {
        Ok(toml::to_string(&table)?)
    }
}

/// Render the contributing layers for `root`, one per line, in the same
/// precedence order [`load_config_layered`] returns them — followed, when any
/// of the three rule arrays merged in a pack, by one `rule <label>: <origin>`
/// line per rule naming the pack (`pack mindtape-tasks` / `pack <path>`) or
/// the layer it came from.
///
/// # Errors
/// Returns an error if the layered config fails to load.
pub(crate) fn render_origin(root: &Path) -> Result<String> {
    let (_config, sources, rule_origins) = load_config_layered(root)?;
    let mut out = String::new();
    for source in &sources {
        out.push_str(&describe_source(source));
        out.push('\n');
    }
    if !rule_origins.is_empty() {
        out.push('\n');
        for entry in &rule_origins {
            out.push_str(&format!(
                "rule {}: {}\n",
                entry.label,
                describe_rule_origin(&entry.origin)
            ));
        }
    }
    Ok(out)
}

/// Render the JSON Schema for `.mindtape/config.toml`, verbatim from
/// [`mindtape::config_schema_json`] — the exact same generator `mt install`
/// writes to the XDG `config.schema.json`, so the printed and installed
/// schema can never diverge. Project-independent: no root is needed.
pub(crate) fn render_schema() -> String {
    config_schema_json()
}

/// One human-readable line describing a layer's origin and, for a real path,
/// whether it exists on disk.
fn describe_source(source: &LayerSource) -> String {
    match source {
        LayerSource::Embedded => "embedded: <built-in>".to_owned(),
        LayerSource::Xdg(path) => format!("xdg: {} ({})", path.display(), existence(path)),
        LayerSource::Dir(path) => format!("dir: {} ({})", path.display(), existence(path)),
        LayerSource::Project(path) => format!("project: {} ({})", path.display(), existence(path)),
    }
}

fn existence(path: &Path) -> &'static str {
    if path.is_file() { "exists" } else { "missing" }
}

/// One rule's origin, short form: which kind of layer it came from directly
/// (the layers section above already names each layer's own path), or, for a
/// pack, `pack <name>` / `pack <path>`.
fn describe_rule_origin(origin: &RuleOrigin) -> String {
    match origin {
        RuleOrigin::Layer(LayerSource::Embedded) => "embedded".to_owned(),
        RuleOrigin::Layer(LayerSource::Xdg(_)) => "xdg".to_owned(),
        RuleOrigin::Layer(LayerSource::Dir(_)) => "dir".to_owned(),
        RuleOrigin::Layer(LayerSource::Project(_)) => "project".to_owned(),
        RuleOrigin::Pack(PackOrigin::Embedded(name)) => format!("pack {name}"),
        RuleOrigin::Pack(PackOrigin::Path(path)) => format!("pack {}", path.display()),
    }
}

